function check(bool $condition,string $message):void{global $passed,$failed;if($condition){$passed++;echo "PASS $message\n";}else{$failed++;echo "FAIL $message\n";}}
function expectError(callable $fn,int|string $expected,string $label):void{
    DB::run('SAVEPOINT expected_error');$matched=false;
    try{$fn();}catch(Throwable $e){$matched=$e instanceof \Learnow\Helpers\HttpError?$e->status===$expected:($expected==='constraint' && $e instanceof PDOException);}
    finally{DB::run('ROLLBACK TO SAVEPOINT expected_error');DB::run('RELEASE SAVEPOINT expected_error');}check($matched,$label);
}
